(function () {
    var progress = {};
    var $ = window.jQuery || window.$;
    var settings = progress.settings = {
        minimum: .08, easing: 'linear', speed: 400, trickle: true,
        trickleSpeed: 200, parent: 'body', template: '<div class="bar"></div>'
    };
    var trickleTimer = null;
    var completionTimer = null;

    function clamp(value, minimum, maximum) {
        return Math.max(minimum, Math.min(maximum, value));
    }
    function stopTrickle() {
        window.clearTimeout(trickleTimer);
        trickleTimer = null;
    }
    function scheduleTrickle() {
        if (!settings.trickle || trickleTimer !== null) return;
        trickleTimer = window.setTimeout(function () {
            trickleTimer = null;
            if (progress.isStarted() && progress.status < 1) {
                progress.trickle();
                scheduleTrickle();
            }
        }, settings.trickleSpeed);
    }
    progress.configure = function (options) {
        Object.keys(options).forEach(function (key) { settings[key] = options[key]; });
        return this;
    };
    progress.status = null;
    progress.set = function (value) {
        value = clamp(value, settings.minimum, 1);
        progress.status = value;
        var element = document.getElementById('dprogress');
        if (!element) {
            element = document.createElement('div');
            element.id = 'dprogress';
            element.innerHTML = settings.template;
            $(element.querySelector('.bar')).css('transition', 'width ' + settings.speed + 'ms ' + settings.easing);
            if (DreamConfig.load_progress === 'center') $(element.querySelector('.bar')).css('margin', 'auto');
            $(settings.parent).prepend(element);
        }
        element.querySelector('.bar').style.width = (100 * value) + '%';
        return this;
    };
    progress.start = function () {
        window.clearTimeout(completionTimer);
        completionTimer = null;
        if (!progress.isStarted() || progress.status === 1) {
            stopTrickle();
            progress.set(settings.minimum);
            var element = document.getElementById('dprogress');
            var bar = element.querySelector('.bar');
            // Reset the completed bar without animating backwards into the next load.
            $(element).hide();
            bar.style.transition = 'none';
            $(element).show();
            void bar.offsetWidth;
            bar.style.transition = 'width ' + settings.speed + 'ms ' + settings.easing;
        } else {
            $('#dprogress').show();
        }
        scheduleTrickle();
        return this;
    };
    progress.inc = function (amount) {
        var value = progress.status;
        if (!progress.isStarted()) return progress.start();
        if (value >= 1) return this;
        if (typeof amount !== 'number') {
            amount = value < .2 ? .1 : value < .5 ? .04 : value < .8 ? .02 : value < .98 ? .005 : 0;
        }
        return progress.set(clamp(value + amount, value, .98));
    };
    progress.trickle = function () { return progress.inc(); };
    progress.done = function () {
        if (!progress.isStarted()) return this;
        stopTrickle();
        window.clearTimeout(completionTimer);
        progress.set(1);
        completionTimer = window.setTimeout(function () {
            completionTimer = null;
            $('#dprogress').hide();
            progress.status = null;
        }, settings.speed);
        return this;
    };
    progress.isStarted = function () { return typeof progress.status === 'number'; };
    progress.isRendered = function () { return !!document.getElementById('dprogress'); };
    window.DProgress = progress;
}());
